import json, glob, os, re
from collections import Counter

files = sorted(glob.glob(os.path.expanduser('~/.claude/projects/*/*.jsonl')),
               key=os.path.getmtime, reverse=True)[:50]

bash = Counter()
mcp = Counter()

def lead_pair(cmd):
    cmd = cmd.strip()
    # take first pipeline/&&/; segment
    cmd = re.split(r'[|;]|&&|\|\|', cmd)[0].strip()
    toks = cmd.split()
    # strip env var prefixes VAR=val
    while toks and re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', toks[0]):
        toks.pop(0)
    # strip wrappers
    while toks and toks[0] in ('sudo','timeout','command','nice','nohup','env'):
        toks.pop(0)
        if toks and toks[0] in ('-','--') : toks.pop(0)
        # timeout takes a duration arg
    if not toks: return None
    c = toks[0]
    sub = toks[1] if len(toks) > 1 and not toks[1].startswith('-') else ''
    return (c, sub)

for f in files:
    try:
        for line in open(f, encoding='utf-8'):
            try: obj = json.loads(line)
            except: continue
            msg = obj.get('message') or {}
            content = msg.get('content')
            if not isinstance(content, list): continue
            for c in content:
                if not isinstance(c, dict) or c.get('type') != 'tool_use': continue
                name = c.get('name','')
                if name == 'Bash':
                    cmd = (c.get('input') or {}).get('command','')
                    p = lead_pair(cmd)
                    if p: bash[p] += 1
                elif name.startswith('mcp__'):
                    mcp[name] += 1
    except Exception as e:
        pass

print("=== BASH (cmd, sub) counts ===")
for (c,s),n in bash.most_common(60):
    print(f"{n:4}  {c} {s}")
print("\n=== MCP counts ===")
for name,n in mcp.most_common(40):
    print(f"{n:4}  {name}")
